"""Audit the user-requested fixed global10 experiment;never runs a model."""
import argparse,hashlib,json,math,statistics,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.search_quality_speed import save
from scripts.report_quality_speed_final import FIELDS,BASE,fmt,table,csvwrite

def main():
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,required=True);a=p.parse_args();root=a.output;out=root/'quality'
 plan=json.loads((out/'plan.json').read_text());completion=json.loads((out/'completion.json').read_text());selection=json.loads((root/'selection.json').read_text());assert completion['complete'] and len(completion['runs'])==18
 for path,sha in plan['source_sha256'].items():assert hashlib.sha256((ROOT/path).read_bytes()).hexdigest()==sha,path
 c=selection['candidates'][0];name=c['name'];cfg=json.loads((ROOT/c['config']).read_text());assert hashlib.sha256((ROOT/c['config']).read_bytes()).hexdigest()==c['config_sha256']
 oldroot=ROOT/'outputs/quality_speed_search_20261106';fast=json.loads((oldroot/'current_probe_summary.json').read_text());old=json.loads((BASE/'summary.json').read_text());rows=[];layers=[];macros=[];audit=[]
 for ds,scenes in plan['datasets'].items():
  for scene in scenes:
   folder=out/'runs'/name/ds/scene;r=json.loads((folder/'result.json').read_text());ref=json.loads((oldroot/'current_probe_quality/runs/cp4_c10_prior_residual_middle18'/ds/scene/'result.json').read_text());assert r['input']==ref['input'] and r['quality_protocol']==ref['quality_protocol'] and r['quality']['complete']
   assert all(r['config'][k]==v for k,v in cfg.items());differences={k for k in set(r['config'])|set(ref['config']) if r['config'].get(k)!=ref['config'].get(k)};assert differences=={'retention','layer_retentions','account_dense_special_query_budget'},differences;q=r['quality']['values'];assert all(math.isfinite(q[k]) for k in FIELDS) and abs(q['cd']-(q['acc']+q['comp'])/2)<1e-9
   t=r['timing'];assert t['warmup']==1 and t['repeats']==3 and t['median_seconds']==statistics.median(v['seconds'] for v in t['samples'])
   m=json.loads((out/'monitors'/f'{name}_{ds}_{scene}.json').read_text());assert m['returncode']==0 and not m['same_gpu_overlap_detected'] and m['max_simultaneous_gpu_applications']==1
   lr=json.loads((folder/'layers.json').read_text());assert len(lr)==24
   frames=r['frames'];shape=r['input']['shape'];np=frames*(shape[-2]//14)*(shape[-1]//14);n=np+frames*5;unique=0;logical=0;cap=0;ref_lr=json.loads((oldroot/'current_probe_quality/runs/cp4_c10_prior_residual_middle18'/ds/scene/'layers.json').read_text())
   for v in lr:
    target=cfg['layer_retentions'][v['layer']];assert v['dense_special_queries_in_budget'] and v['dense_special_query_count']==frames*5 and v['fine_clusters']==math.floor(.1*np)
    assert v['output_retention_target']==target
    bound=(n-frames*5)*(v['patch_budget']+frames*5)+frames*5*n
    assert v['output_unique_qk_cap_per_head']==bound and bound<=target*n*n+1e-3 and v['final_unique_qk_per_head']<=bound
    aux=v['current_probe_qk_per_head'];physical=v['direct_logical_main_qk_per_head']+aux+v['dense_special_query_physical_qk_per_head'];assert physical/n**2<=.25
    unique+=v['final_unique_qk_per_head'];logical+=physical;cap+=bound
    layers.append(dict(dataset=ds,scene=scene,layer=v['layer'],tokens=n,target_output_density=target,actual_unique_density=v['final_unique_qk_per_head']/n**2,output_unique_qk_per_head=v['final_unique_qk_per_head'],output_unique_qk_cap_per_head=bound,patch_budget=v['patch_budget'],special_keys=v['special_keys'],dense_special_queries=v['dense_special_query_count'],probe_qk_dense_fraction=aux/n**2,repeated_dense_special_qk_fraction=v['dense_special_query_physical_qk_per_head']/n**2,total_logical_qk_dense_fraction=physical/n**2,unused_patch_budget_mean=v['unused_budget_mean'],**{f'state_{i}_clusters_mean':v.get(f'state_{i}_clusters_mean') for i in [0,1,5,10]}))
   density=unique/(24*n*n);assert density<=.1+1e-12 and cap<=.1*24*n*n+1e-3
   row=dict(dataset=ds,scene=scene,method=name,frames=frames,**q,seconds=t['median_seconds'],reference_batch_fast14_seconds=ref['timing']['median_seconds'],historical_fast14_speedup=ref['timing']['median_seconds']/t['median_seconds'],actual_unique_density=density,output_density_cap=cap/(24*n*n),reference_actual_unique_density=statistics.mean(v['actual_unique_density'] for v in ref_lr),total_logical_qk_dense_fraction=logical/(24*n*n),unique_qk_per_head=unique,dense_qk_per_head=24*n*n,warm_peak_allocated_gib=max(v['peak_allocated_gib'] for v in t['samples']),warm_peak_reserved_gib=max(v['peak_reserved_gib'] for v in t['samples']),cold_seconds=t['cold_samples'][0]['seconds'],including_cold_peak_allocated_gib=max(v['peak_allocated_gib'] for v in t['samples']+t['cold_samples']),speedup_vs_dense=None,speedup_reason='Unchanged Dense not rerun,no paired Dense timing;reference target times are from previous batch');rows.append(row);save(folder/'reporting.json',dict(row,units=dict(auc03='fraction',auc30='fraction',f1='fraction',acc='m',comp='m',cd='m'),quality_complete=True))
   audit.append(dict(dataset=ds,scene=scene,quality_complete=True,frozen_source_and_config_match=True,matched_reference_input_and_protocol=True,gpu_uuid=m['gpu_uuid'],no_same_gpu_overlap=True,actual_global_output_density_le10pct=True))
  rr=[r for r in rows if r['dataset']==ds];ref=next(r for r in fast['macro'] if r['dataset']==ds)
  macro=dict(dataset=ds,method=name,scenes=len(rr),**{k:statistics.mean(r[k] for r in rr) for k in FIELDS},seconds=statistics.mean(r['seconds'] for r in rr),reference_batch_fast14_seconds=ref['seconds'],historical_fast14_speedup=ref['seconds']/statistics.mean(r['seconds'] for r in rr),actual_unique_density=statistics.mean(r['actual_unique_density'] for r in rr),edge_weighted_unique_density=sum(r['unique_qk_per_head'] for r in rr)/sum(r['dense_qk_per_head'] for r in rr),reference_actual_unique_density=statistics.mean(r['reference_actual_unique_density'] for r in rr),total_logical_qk_dense_fraction=statistics.mean(r['total_logical_qk_dense_fraction'] for r in rr),warm_peak_allocated_gib=max(r['warm_peak_allocated_gib'] for r in rr),warm_peak_reserved_gib=max(r['warm_peak_reserved_gib'] for r in rr),including_cold_peak_allocated_gib=max(r['including_cold_peak_allocated_gib'] for r in rr),mean_cold_seconds=statistics.mean(r['cold_seconds'] for r in rr),speedup_vs_dense=None)
  macro['relative_changes_percent_vs_fast14']={k:100*(macro[k]/ref[k]-1) for k in FIELDS};macro['all_six_not_worse_than_fast14']=all(macro[k]>=ref[k] if k in ('auc03','auc30','f1') else macro[k]<=ref[k] for k in FIELDS);macros.append(macro)
 summary=dict(complete=True,macro=macros,selection=selection,comparison_fast14=fast['macro'],comparison_A12=old['macro'],historical_controls=fast['historical_controls'],control_reruns=False,dense_speedup=None,dense_speedup_reason='No paired Dense rerun authorized',source_audit_passed=True)
 save(root/'summary.json',summary);save(root/'audit.json',dict(passed=True,runs=len(rows),rows=audit));csvwrite(root/'per_scene.csv',rows);csvwrite(root/'per_layer.csv',layers);csvwrite(root/'macro.csv',[{k:v for k,v in r.items() if not isinstance(v,dict)} for r in macros])
 compare=[]
 for ds in plan['datasets']:
  compare.extend(dict(r,label='原A12') for r in old['macro'] if r['dataset']==ds);compare.extend(dict(r,label='快速14%（原分组预算命名）') for r in fast['macro'] if r['dataset']==ds);compare.extend(dict(r,label='整体10%总预算') for r in macros if r['dataset']==ds)
 lines=['# 整体10%保留预算评测','', '只评测用户改动的配置；已有A12、快速14%、Dense和SAF3R结果复用。7Scenes全七场景各128帧，ETH3D原11场景14–76帧，共18场景。完整pose+recon_unposed，等场景宏平均；AUC/F1为%，ACC/Comp/CD为m，CD=(ACC+Comp)/2（未平方）。','',table(['数据集','方案','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %'],[[r['dataset'],r['label'],*[fmt(k,r[k]) for k in FIELDS]] for r in compare]),'', '## 预算定义与实际边数','', '仅改快速14%版的分层预算及其核算方式。10%簇数、256Query组、4探针、History A、补偿和状态/预算求解等均保留。旧10/18/10%层权重统一乘5/7，目标浅/中/深输出密度上限7.142857/12.857143/7.142857%，24层合计上限10%，不是每层固定10%。','', 'D个特殊Query保留全Key。非特殊Query的每组Key上限按floor((r*N²-D*N)/(N-D))计算，再扣除始终保留的特殊Key。因此最终唯一输出边含特殊Query扩展，而不是旧配置中只核算每组Key。旧快速14%名称为原分组预算，特殊Query修正后实际输出密度略高；本表如实给出。状态预算是上限，不强行添加无收益Key填满；实际可能略低于10%。','',table(['数据集','旧快速版实际保留 %','新实际保留 %（等场景）','新实际保留 %（边加权）','含探针/重复特殊QK逻辑量 %Dense'],[[r['dataset'],f"{100*r['reference_actual_unique_density']:.5f}",f"{100*r['actual_unique_density']:.5f}",f"{100*r['edge_weighted_unique_density']:.5f}",f"{100*r['total_logical_qk_dense_fraction']:.5f}"] for r in macros]),'', '探针不是最终输出Mask的一部分；两个完整Key扫描和特殊Query重复执行计入逻辑QK和完整前向时间，不能把10%唯一输出边说成全部计算只有Dense的10%。每层actual<=cap，24层总体<=10%已审计。','', '## 完整前向与显存','',table(['数据集','旧快速版历史 s','本轮 s','历史参考加速','热allocated峰值 GiB','热reserved峰值 GiB','含首次峰值 GiB','首次前向均值 s','正式Dense配对加速'],[[r['dataset'],f"{r['reference_batch_fast14_seconds']:.6f}",f"{r['seconds']:.6f}",f"{r['historical_fast14_speedup']:.4f}x",f"{r['warm_peak_allocated_gib']:.3f}",f"{r['warm_peak_reserved_gib']:.3f}",f"{r['including_cold_peak_allocated_gib']:.3f}",f"{r['mean_cold_seconds']:.3f}",'N/A'] for r in macros]),'', 'GPU4/5/6逐卡独占监控，1预热+3完整前向中位数，再等场景平均。包含聚类、观测、预算、索引、历史、重排、特殊Query和预测头，加载/CPU几何评估不在前向内。原快速版时间来自quality_speed_search_20261106上一批，非本轮配对。未重跑Dense或SAF3R，正式Dense配对速度N/A（Dense定义1.00x）。首次前向含进程初始化/自动选核/图捕获，但未清系统磁盘编译缓存。','', '## 相对快速14%的质量变化','',table(['数据集',*[k+'相对变化 %' for k in FIELDS],'六项均不退化'],[[r['dataset'],*[f"{r['relative_changes_percent_vs_fast14'][k]:+.3f}" for k in FIELDS],r['all_six_not_worse_than_fast14']] for r in macros]),'', '不依据本轮目标分数继续调预算，不把低预算当成保证质量不变。本轮仅一次冻结配置验收，没有重新选择最好重复。','', '## 历史控制质量（未重跑）','',table(['数据集','历史控制','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %'],[[r['dataset'],r['method'],*[fmt(k,r[k]) for k in FIELDS]] for r in fast['historical_controls']]),'', '历史控制来自combined_reuse_20261031等既有批次，旧控制文件缺checkpoint SHA，不能追认严格字节一致。SAF3R为lazy first-correspondence-head Top4/frame，非论文DINO Top-K。完整当前/快速版输入、checkpoint SHA、预处理和几何协议一致。','', '7Scenes阈值/下采样0.05/0.0078125m；ETH3D0.25/0.0390625m。checkpoint SHA b08a43baa2db1aad9718e71e098831b8ad32f6f6826c802e9eb714aa34420969。','', '## 逐场景完整六指标','',table(['数据集','场景','帧','AUC3 %','AUC30 %','ACC m','Comp m','CD m','F1 %','秒','实际保留 %'],[[r['dataset'],r['scene'],r['frames'],*[fmt(k,r[k]) for k in FIELDS],f"{r['seconds']:.6f}",f"{100*r['actual_unique_density']:.5f}"] for r in rows]),'', '22项预算/数值测试通过（测试不是质量评估，六项几何N/A并注明原因）。原始JSON、帧表、配置、源码SHA、源码gzip快照、GPU独占监控、逐层状态/预算/QK计数与完整CSV均保留。旧配置默认关闭新预算核算开关，原方法未改动。']
 (root/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(macros,indent=2))

